	/* 0x3c21c0 */
	m_unfinished_tex = zdb::CWorld::GetTexHandle("hud_checkbox.tif");
	m_completed_tex = zdb::CWorld::GetTexHandle("hud_check.tif");
	m_background_tex = zdb::CWorld::GetTexHandle("team_background.tif");
